import axios from 'axios';
import type { AxiosInstance } from 'axios';
import { setupInterceptors } from './interceptors';

const http: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL ?? '/api',
  timeout: 30_000,
  headers: {
    'Content-Type': 'application/json',
  },
});

setupInterceptors(http);

export default http;

import type { AxiosInstance, InternalAxiosRequestConfig, AxiosResponse, AxiosError } from 'axios';

export function setupInterceptors(instance: AxiosInstance) {
  // ─── Request: Token ekle ─────────────────────────────────────────────────
  instance.interceptors.request.use(
    (config: InternalAxiosRequestConfig) => {
      const token = localStorage.getItem('access_token');
      if (token && config.headers) {
        config.headers.Authorization = `Bearer ${token}`;
      }
      return config;
    },
    (error) => Promise.reject(error),
  );

  // ─── Response: Hata yönetimi ─────────────────────────────────────────────
  instance.interceptors.response.use(
    (response: AxiosResponse) => response,
    async (error: AxiosError) => {
      const originalRequest = error.config as InternalAxiosRequestConfig & { _retry?: boolean };

      // 401 — Token yenile
      if (error.response?.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;

        try {
          const refreshToken = localStorage.getItem('refresh_token');
          const { data } = await instance.post('/auth/refresh', { refreshToken });

          localStorage.setItem('access_token', data.accessToken);
          if (originalRequest.headers) {
            originalRequest.headers.Authorization = `Bearer ${data.accessToken}`;
          }

          return instance(originalRequest);
        } catch {
          // Refresh başarısız → logout
          localStorage.removeItem('access_token');
          localStorage.removeItem('refresh_token');
          window.location.href = '/login';
        }
      }

      return Promise.reject(error);
    },
  );
}

import { createContext, useContext, useState, useEffect } from 'react';
import http from '@/lib/http';

export interface AuthUser {
  id: string;
  username: string;
  email: string;
  roles: string[];
}

export interface AuthContextValue {
  user: AuthUser | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
}

export const AuthContext = createContext<AuthContextValue | null>(null);

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

interface AuthProviderProps {
  children: React.ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Uygulama açıldığında mevcut token ile kullanıcıyı getir
  useEffect(() => {
    const token = localStorage.getItem('access_token');
    if (!token) {
      setIsLoading(false);
      return;
    }

    http
      .get<AuthUser>('/auth/me')
      .then((res) => setUser(res.data))
      .catch(() => {
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
      })
      .finally(() => setIsLoading(false));
  }, []);

  const login = async (username: string, password: string) => {
    const { data } = await http.post<{ accessToken: string; refreshToken: string }>(
      '/auth/login',
      { username, password },
    );
    localStorage.setItem('access_token', data.accessToken);
    localStorage.setItem('refresh_token', data.refreshToken);

    const me = await http.get<AuthUser>('/auth/me');
    setUser(me.data);
  };

  const logout = () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    setUser(null);
    window.location.href = '/login';
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated: !!user, isLoading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

import http from '@/lib/http';
import type { AuthUser } from '@/contexts/auth/AuthContext';

export function useAuth() {
  // AuthProvider'dan useAuth'u re-export eder; bu hook burada kullanılır
  // Doğrudan AuthContext'ten import edin: import { useAuth } from '@/contexts/auth/AuthContext'
}

export async function getMe(): Promise<AuthUser> {
  const { data } = await http.get<AuthUser>('/auth/me');
  return data;
}

import http from '@/lib/http';
import type { AxiosRequestConfig } from 'axios';

/**
 * Tüm servis sınıfları için temel sınıf.
 * Extend ederek proje servislerinizi oluşturun:
 *
 * @example
 * class UserService extends BaseService {
 *   constructor() { super('/users'); }
 *   getAll() { return this.get<User[]>(); }
 *   getById(id: string) { return this.get<User>(`/${id}`); }
 * }
 * export const userService = new UserService();
 */
export abstract class BaseService {
  protected readonly basePath: string;

  constructor(basePath: string) {
    this.basePath = basePath;
  }

  protected get<T>(path = '', config?: AxiosRequestConfig) {
    return http.get<T>(`${this.basePath}${path}`, config);
  }

  protected post<T>(path = '', data?: unknown, config?: AxiosRequestConfig) {
    return http.post<T>(`${this.basePath}${path}`, data, config);
  }

  protected put<T>(path = '', data?: unknown, config?: AxiosRequestConfig) {
    return http.put<T>(`${this.basePath}${path}`, data, config);
  }

  protected patch<T>(path = '', data?: unknown, config?: AxiosRequestConfig) {
    return http.patch<T>(`${this.basePath}${path}`, data, config);
  }

  protected delete<T>(path = '', config?: AxiosRequestConfig) {
    return http.delete<T>(`${this.basePath}${path}`, config);
  }
}
